    ('a616ccfb-317e-4642-84a0-a18ca30a3603', '66a1445d-47eb-49b3-8fe1-06997e4273bf', '8c374e00-7af4-43d1-8c8f-15abb4373727', false, '{"selectedOptions":[3]}', 64, 'practice', now() - interval '465586 seconds', 'not sure', 'missing'),
