    ('03fbee4c-896c-4c75-8d8e-b94b57b715bc', '66a1445d-47eb-49b3-8fe1-06997e4273bf', '57f4bac0-8d13-498d-8567-afbab828b3f4', false, '{"selectedOptions":[3]}', 105, 'practice', now() - interval '117131 seconds', null, 'missing'),
