    ('a87f24b1-e57e-4b9e-87b4-fd44f42cc36c', 'fd812a16-b45c-407e-88da-a30137e5d97b', '83f510d4-5955-40f6-8ccf-1c0d0e3c84f3', false, '{"selectedOptions":[1]}', 106, 'practice', now() - interval '548755 seconds', null, 'missing'),
