    ('12b39adc-213e-4302-827f-70b3b458583a', 'fd812a16-b45c-407e-88da-a30137e5d97b', '86a8521f-3073-45e5-89bf-0d0d84d2f58a', true, '{"selectedOptions":[2]}', 118, 'practice', now() - interval '547977 seconds', 'The farther you stand, the smaller the mirror makes your image.', 'flawed'),
    ('71b470e9-1007-4d69-8377-14113fa18924', 'fd812a16-b45c-407e-88da-a30137e5d97b', '86a8521f-3073-45e5-89bf-0d0d84d2f58a', true, '{"selectedOptions":[2]}', 100, 'practice', now() - interval '547928 seconds', 'because a plane mirror always forms an image the same size as the object; it only looks smaller from farther away because it is more distant', 'sound'),
    ('779ac436-8b7d-445d-8bdc-e5fa667d25a8', 'fd812a16-b45c-407e-88da-a30137e5d97b', '86a8521f-3073-45e5-89bf-0d0d84d2f58a', true, '{"selectedOptions":[2]}', 54, 'practice', now() - interval '547870 seconds', null, 'missing'),
    ('b6728c32-9f66-4395-8b7f-2e80f70121cf', 'fd812a16-b45c-407e-88da-a30137e5d97b', 'c5e4ee4c-895f-4efa-8fc5-a33cf85a685a', true, '{"selectedOptions":[1]}', 29, 'practice', now() - interval '547760 seconds', 'because the distance to her image falls from 3 + 3 = 6 m to 2 + 2 = 4 m, a decrease of 2 m, because the image moves with her', 'sound'),
