    ('c1aa6323-e611-4efe-84d4-f658c689168c', 'fd812a16-b45c-407e-88da-a30137e5d97b', '0f25728e-daad-4fe2-8fe0-c906087dd055', false, '{"selectedOptions":[3]}', 31, 'practice', now() - interval '456396 seconds', 'not sure', 'missing'),
