    ('46d044fc-dfd0-484c-8d5b-d9e08dc0e7c5', 'fd812a16-b45c-407e-88da-a30137e5d97b', 'edf67eb8-a7eb-431b-8693-5037ea7581ce', false, '{"selectedOptions":[3]}', 52, 'practice', now() - interval '456196 seconds', null, 'missing'),
    ('52fb6057-24dc-4602-873f-229a7bb7c79d', 'fd812a16-b45c-407e-88da-a30137e5d97b', 'edf67eb8-a7eb-431b-8693-5037ea7581ce', false, '{"selectedOptions":[1]}', 103, 'practice', now() - interval '456116 seconds', 'not sure', 'missing'),
    ('6992967c-ccaf-4cc3-83e2-67cb187d31c6', 'fd812a16-b45c-407e-88da-a30137e5d97b', 'edf67eb8-a7eb-431b-8693-5037ea7581ce', true, '{"selectedOptions":[2]}', 79, 'practice', now() - interval '456074 seconds', 'because free electrons move randomly, but a net flow of charge needs a potential difference across the conductor', 'sound'),
    ('a33c3814-eb45-4843-8fa0-9376111485cf', 'fd812a16-b45c-407e-88da-a30137e5d97b', '57f4bac0-8d13-498d-8567-afbab828b3f4', true, '{"selectedOptions":[2]}', 96, 'practice', now() - interval '456032 seconds', 'because by Ohm''s law I = V/R; R is fixed for the conductor, so doubling V doubles I', 'sound'),
