    ('cb0e46cd-b8f6-4ea6-8052-51bcf5e7d02e', 'fd812a16-b45c-407e-88da-a30137e5d97b', '8f91851d-659c-4af3-8d50-fe7d815e5407', true, '{"selectedOptions":[3]}', 85, 'practice', now() - interval '455851 seconds', null, 'missing'),
    ('5008ce8e-6a90-45ed-8f94-64a428afa4ee', 'fd812a16-b45c-407e-88da-a30137e5d97b', '8f91851d-659c-4af3-8d50-fe7d815e5407', true, '{"selectedOptions":[3]}', 84, 'practice', now() - interval '455802 seconds', 'because h = I²Rt = 2² × 5 × 10 = 200 J', 'sound'),
