    ('d18cba72-ae18-4523-8dc2-27e9c07c282a', 'fed9cd62-cac8-4110-8df5-9aa5407ea607', '063cbf2c-ec6d-4cca-839d-81bd240b456f', true, '{"selectedOptions":[0]}', 61, 'practice', now() - interval '285926 seconds', 'because straight-line rays from the top and bottom of the flame cross at the pinhole, so the top of the object maps to the bottom of the image', 'sound'),
    ('22ccab0a-20e9-44a1-800e-21a452400554', 'fed9cd62-cac8-4110-8df5-9aa5407ea607', 'c62151ab-4ce4-430b-83c5-96bb3a4055f1', true, '{"selectedOptions":[1]}', 95, 'practice', now() - interval '285842 seconds', 'because light travels in straight lines in a uniform medium, so the region behind an opaque object receives no light', 'sound'),
    ('280acbf8-6130-4444-8b88-0c8e58a42200', 'fed9cd62-cac8-4110-8df5-9aa5407ea607', '063cbf2c-ec6d-4cca-839d-81bd240b456f', true, '{"selectedOptions":[0]}', 21, 'practice', now() - interval '285777 seconds', 'because straight-line rays from the top and bottom of the flame cross at the pinhole, so the top of the object maps to the bottom of the image', 'sound'),
