    ('04796d4f-37f6-4efa-8a1e-0b3ede9ebb5b', '7e98a5c9-93e9-4c06-8338-755f0bf235b1', '88f87cea-896e-4b12-88f6-f92d31f32705', false, '{"selectedOptions":[0]}', 87, 'assessment', now() - interval '779192 seconds', 'A convex lens will help a myopic person see distant objects.', 'flawed'),
    ('ee9c52af-fe7d-4f93-8109-e526bf6e4707', '7e98a5c9-93e9-4c06-8338-755f0bf235b1', '6ca49128-eaea-41b4-8324-b19fdbcaca07', true, '{"selectedOptions":[1]}', 45, 'assessment', now() - interval '779117 seconds', 'because the earth wire normally carries no current; in a fault it lets current flow safely to the ground so the user is not shocked', 'sound'),
    ('f5162889-4474-490c-8ec6-dfbea096ecff', '7e98a5c9-93e9-4c06-8338-755f0bf235b1', 'de06817c-4d9f-400d-8dec-1467419f33db', true, '{"selectedOptions":[0]}', 44, 'assessment', now() - interval '779042 seconds', 'because a fuse must melt quickly when excess current heats it, breaking the circuit, so it needs a low melting point', 'sound'),
    ('4424d69b-d60c-46c2-81bb-983184ef811d', '7e98a5c9-93e9-4c06-8338-755f0bf235b1', '86a8521f-3073-45e5-89bf-0d0d84d2f58a', true, '{"selectedOptions":[2]}', 30, 'assessment', now() - interval '778967 seconds', 'because a plane mirror always forms an image the same size as the object; it only looks smaller from farther away because it is more distant', 'sound'),
