    ('6c3c933e-c1b5-4ea3-839a-31f05962f1c9', '7e98a5c9-93e9-4c06-8338-755f0bf235b1', '57f4bac0-8d13-498d-8567-afbab828b3f4', false, '{"selectedOptions":[0]}', 48, 'practice', now() - interval '720680 seconds', null, 'missing'),
    ('6c3e367f-9e2f-4f4b-8817-626f659e9131', '7e98a5c9-93e9-4c06-8338-755f0bf235b1', 'e8c0f160-32d0-4f92-809c-bf185454600f', true, '{"selectedOptions":[0]}', 26, 'practice', now() - interval '720625 seconds', 'because by convention, outside a magnet the field lines emerge from the north pole and enter the south pole', 'sound'),
