    ('93e17d39-dfaf-4e1b-8d48-1a0457b057b6', 'be5c54e8-4f64-4f83-89d7-5eb4fa8d12e5', '7601cfc4-3612-4392-81a1-6f58fb3b7335', false, '{"selectedOptions":[1]}', 72, 'practice', now() - interval '722729 seconds', 'not sure', 'missing'),
