    ('3d299ea9-8648-424e-8269-aa77102615e5', 'e2b50a35-aef4-4009-82b9-b487140d57e1', 'cfe47243-9ba2-44b4-8749-5d5f805ea814', false, '{"selectedOptions":[0]}', 103, 'practice', now() - interval '550670 seconds', 'not sure', 'missing'),
