    ('8314bbed-fe2f-4307-8b7d-a9977643f022', 'ed290615-b614-470a-873c-9e37cffc3f46', '6d01d352-1fad-4078-8620-a0c767eababd', true, '{"selectedOptions":[0]}', 93, 'practice', now() - interval '461319 seconds', null, 'missing'),
