    ('92020d78-d5ba-4a5a-8543-f2e752a996b8', 'ed290615-b614-470a-873c-9e37cffc3f46', '5e8571a5-2351-4fe0-8091-c30478579d1b', true, '{"selectedOptions":[3]}', 54, 'practice', now() - interval '198804 seconds', 'because the reflected ray makes 50° with the first mirror, so it meets the perpendicular mirror at 40° to its surface, giving an angle of incidence of 90° − 40° = 50°', 'sound'),
    ('1296faa2-cbf6-4c62-88fa-7a876a374474', 'ed290615-b614-470a-873c-9e37cffc3f46', '3c5eeb9a-a95e-42bb-8f0a-132371d6e2af', true, '{"selectedOptions":[2]}', 49, 'practice', now() - interval '198717 seconds', null, 'missing'),
