    ('542cb24f-a2c0-4cbe-86ef-ac37780d2518', 'ed290615-b614-470a-873c-9e37cffc3f46', '677c607c-c065-4907-8428-16acf59cfda5', true, '{"selectedOptions":[0]}', 115, 'practice', now() - interval '198485 seconds', 'because now V = IR = 0.4 × 5 = 2 V; for 0.8 A through the same 5 Ω, V = 0.8 × 5 = 4 V', 'sound'),
    ('18ea6f97-9934-468c-89b6-d881c80c720f', 'ed290615-b614-470a-873c-9e37cffc3f46', '677c607c-c065-4907-8428-16acf59cfda5', true, '{"selectedOptions":[0]}', 109, 'practice', now() - interval '198378 seconds', 'because now V = IR = 0.4 × 5 = 2 V; for 0.8 A through the same 5 Ω, V = 0.8 × 5 = 4 V', 'sound'),
    ('c9db9846-a292-409b-823a-5de3145c8159', 'ed290615-b614-470a-873c-9e37cffc3f46', '677c607c-c065-4907-8428-16acf59cfda5', true, '{"selectedOptions":[0]}', 57, 'practice', now() - interval '198315 seconds', 'because now V = IR = 0.4 × 5 = 2 V; for 0.8 A through the same 5 Ω, V = 0.8 × 5 = 4 V', 'sound'),
