    ('b4113d8a-5084-4101-895d-a241acba9da5', 'ed290615-b614-470a-873c-9e37cffc3f46', '5e83186b-b594-404d-82f8-3de6f40b50b0', true, '{"selectedOptions":[1]}', 47, 'practice', now() - interval '197630 seconds', 'because r = ρl/A: resistance falls with shorter length and with larger cross-sectional area', 'sound'),
    ('ebcbe46c-891e-449e-818b-f4c510e182a8', 'ed290615-b614-470a-873c-9e37cffc3f46', '59a576c7-3d0d-44a2-8e07-300875cbbea8', true, '{"selectedOptions":[2]}', 52, 'practice', now() - interval '197520 seconds', 'because doubling l halves A (same volume), so R = ρl/A becomes ρ(2l)/(A/2) = 4R', 'sound'),
