    ('668cfd7b-fd5e-4bc5-825d-0fecaf5930ec', 'a0477dab-48ac-426a-8676-4869b5013a99', '7601cfc4-3612-4392-81a1-6f58fb3b7335', true, '{"selectedOptions":[2]}', 109, 'practice', now() - interval '453820 seconds', null, 'missing'),
