    ('98e72547-1063-4b24-899d-c17f4e8e0c0f', 'a0477dab-48ac-426a-8676-4869b5013a99', '86a8521f-3073-45e5-89bf-0d0d84d2f58a', true, '{"selectedOptions":[2]}', 44, 'practice', now() - interval '369742 seconds', 'because a plane mirror always forms an image the same size as the object; it only looks smaller from farther away because it is more distant', 'sound'),
    ('02edda49-4bac-4ab2-8f2b-392b53e35474', 'a0477dab-48ac-426a-8676-4869b5013a99', '03cf46c1-c050-4597-829e-9732e621b333', true, '{"selectedOptions":[1]}', 63, 'practice', now() - interval '369693 seconds', 'because a convex mirror always gives an erect, diminished image and covers a wide field of view, which is ideal for seeing traffic behind', 'sound'),
