    ('9280e50c-eafd-4104-8f09-62ef305321cf', '84b0f493-42ce-4d9d-8d2c-d82f5cf29837', '5e8571a5-2351-4fe0-8091-c30478579d1b', false, '{"selectedOptions":[2]}', 91, 'practice', now() - interval '118682 seconds', null, 'missing'),
