    ('7ddb9bfa-e1e7-4dbb-8adc-71461dee7b9c', '7d4b9ad8-6085-4a1f-8b0b-94b47ceced3e', 'c8e59f98-4f5c-4d44-8751-0653b147efe4', false, '{"selectedOptions":[0]}', 71, 'practice', now() - interval '547725 seconds', null, 'missing'),
