    ('335f66d4-41fb-46cd-86cd-2775637183c9', 'a5cba874-c95d-4ff2-8fa4-0911a427f3ea', 'e050b0d8-cb71-41cf-8059-c1c1a8feefce', true, '{"selectedOptions":[1]}', 38, 'practice', now() - interval '282728 seconds', 'because a convex mirror diverges light; parallel rays reflect so that they appear to come from the principal focus behind the mirror', 'sound'),
    ('82446796-1942-4e95-8a13-1747841d44b1', 'a5cba874-c95d-4ff2-8fa4-0911a427f3ea', 'a31d27c0-6592-4eaf-8e2d-f6b1805b7106', true, '{"selectedOptions":[3]}', 73, 'practice', now() - interval '282642 seconds', 'because a ray through the centre of curvature meets the mirror along the normal, so it is reflected back along the same path', 'sound'),
