    ('f68de2bd-5b5a-4606-8711-00cdd0eb3c9b', 'a3336cb3-5075-4550-8b12-ee7ccf996ff5', 'edf67eb8-a7eb-431b-8693-5037ea7581ce', true, '{"selectedOptions":[2]}', 34, 'practice', now() - interval '628136 seconds', 'because free electrons move randomly, but a net flow of charge needs a potential difference across the conductor', 'sound'),
