    ('9d339fa6-b628-42f3-82d1-d766332fe222', 'a3336cb3-5075-4550-8b12-ee7ccf996ff5', 'b880fcf6-9d8f-4c5d-8cf3-03391dafa270', true, '{"selectedOptions":[0]}', 101, 'practice', now() - interval '626974 seconds', 'because a voltmeter compares two points, so it is connected in parallel across the component', 'sound'),
    ('aff5ce48-2fb6-4202-88f8-d77e69fdbce1', 'a3336cb3-5075-4550-8b12-ee7ccf996ff5', 'bf704d8a-1df2-478f-8a52-8fc74d9845db', true, '{"selectedOptions":[1]}', 32, 'practice', now() - interval '626910 seconds', 'because v = W/Q: potential difference is energy per unit charge between two points; charge per second is current', 'sound'),
    ('382cfc9e-d222-44cc-88d4-6147f8f6e955', 'a3336cb3-5075-4550-8b12-ee7ccf996ff5', '0e26472d-1d73-4655-8d35-0755bcfe4c73', false, '{"selectedOptions":[0]}', 116, 'practice', now() - interval '626845 seconds', 'not sure', 'missing'),
