    ('ee184eb7-93ff-4a45-8d78-ad4b88ec9065', 'a3336cb3-5075-4550-8b12-ee7ccf996ff5', '6fbd16c9-89e2-4be5-84b1-51d401722a0b', false, '{"selectedOptions":[1]}', 75, 'practice', now() - interval '540413 seconds', null, 'missing'),
    ('af47b853-5867-4a2d-83f6-f13a952590cc', 'a3336cb3-5075-4550-8b12-ee7ccf996ff5', '8b85080d-82ba-4b9d-8fcc-95aabf40a3a4', true, '{"selectedOptions":[0]}', 71, 'practice', now() - interval '540326 seconds', 'because the object is placed to the left, and distances measured against the direction of incident light are negative, so u is always negative', 'sound'),
