    ('4ad33755-9a97-4228-85ce-b0bdb620c431', 'a3336cb3-5075-4550-8b12-ee7ccf996ff5', 'eb4f69d2-0789-422c-8ce4-f41abd669bba', false, '{"selectedOptions":[0]}', 37, 'practice', now() - interval '539864 seconds', 'not sure', 'missing'),
    ('33c21eab-f768-4520-82e3-a630cd3139ee', 'a3336cb3-5075-4550-8b12-ee7ccf996ff5', '21b51be5-6972-4255-84ba-79cee8819339', true, '{"selectedOptions":[3]}', 69, 'practice', now() - interval '539798 seconds', 'because n = c/v = (3 × 10⁸)/(2 × 10⁸) = 1.5; a refractive index is never less than 1', 'sound'),
    ('908c4fe2-681f-4678-8c20-c17552efaec2', 'a3336cb3-5075-4550-8b12-ee7ccf996ff5', '7a38d880-3b17-4284-89e5-9520930e929b', true, '{"selectedOptions":[0]}', 46, 'practice', now() - interval '539743 seconds', 'because n = c/v, so n = 2.42 means the speed of light in vacuum is 2.42 times its speed in diamond', 'sound'),
