    ('dd789bd6-5281-4fa5-8866-54fd4e9dca0e', 'a3336cb3-5075-4550-8b12-ee7ccf996ff5', 'f2401e60-0d3e-47e6-8be2-7ae219da9898', true, '{"selectedOptions":[2]}', 40, 'practice', now() - interval '539372 seconds', null, 'missing'),
